    [Theory]
    [MemberData(nameof(OriginalCases))]
    public void Original_campsite_and_lava_trap_match_whole_grid_rng_and_structure_order(int kind,int seed,int profile,bool returned,string grid,string rng,int[] structures,int[] protectedStructures)
    {
        var workspace=new Workspace(180,kind==0?500:220);workspace.InitializeVanillaStructureMap();
        for(int x=0;x<180;x++)for(int y=0;y<workspace.HeightTiles;y++)workspace.TileStore.Set(x,y,kind==0?LavaTile(profile,x,y):CampTile(profile,x,y));
        if(kind==1&&profile>=16)
        {
            var effects=new WorldGenerationEntityEffects1458(new RuntimeNpcStore(),new RuntimeProjectileStore());workspace.AttachEntityEffects(effects);
            for(int i=0;i<6;i++){int px=(84+i*2)*16,py=(profile==16?93:profile==17?95:60)*16;Assert.True(effects.RetainTownNpc(new(22),px,py,true,90,90,out _));}
        }
        var random=new LeafRandom(seed);Assert.Equal(returned,kind==0?MicroLavaTrap1458.Place(workspace,random,90,100):MicroCampsite1458.Place(workspace,random,90,90));
        using var bytes=new MemoryStream();using(var writer=new BinaryWriter(bytes))
            for(int x=0;x<180;x++)for(int y=0;y<workspace.HeightTiles;y++){var tile=workspace.TileStore.Get(x,y);writer.Write(tile.Type);writer.Write(tile.Wall);writer.Write(tile.FrameX);writer.Write(tile.FrameY);writer.Write(tile.LiquidAmount);writer.Write((byte)tile.LiquidKind);writer.Write(tile.Shape);writer.Write(tile.TileColor);writer.Write(tile.WallColor);writer.Write((ushort)tile.Flags);}
        Assert.Equal(grid,Convert.ToHexString(SHA256.HashData(bytes.ToArray())));
        using var state=new MemoryStream();using(var writer=new BinaryWriter(state)){writer.Write((uint)typeof(VanillaUnifiedRandom1458).GetField("inext",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(random.Source)!);foreach(int value in (int[])typeof(VanillaUnifiedRandom1458).GetField("seedArray",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(random.Source)!)writer.Write(value);}
        Assert.Equal(rng,Convert.ToHexString(SHA256.HashData(state.ToArray())));
        static int[] Flatten(WorldTileRegion[] values)=>values.SelectMany(r=>new[]{r.X,r.Y,r.Width,r.Height}).ToArray();
        Assert.Equal(structures,Flatten(workspace.VanillaStructureMap.CaptureStructures()));Assert.Equal(protectedStructures,Flatten(workspace.VanillaStructureMap.CaptureProtectedStructures()));
    }
    private static WorldTile LavaTile(int profile,int x,int y)
    {
        int roof=profile==11?302:110,floor=profile==12?117:profile==13?160:123;
        var tile=new WorldTile{Type=(ushort)(y>=floor?1:0),Wall=15,FrameX=18,FrameY=36,TileColor=7,WallColor=9,Flags=y>=floor?WorldTileFlags.Active:0};
        if(y>=roof&&y<roof+3){tile.Type=1;tile.Flags|=WorldTileFlags.Active;}
        if(x>=85&&x<=95&&y>=95&&y<=105){tile.LiquidAmount=255;tile.LiquidKind=WorldLiquidKind.Lava;}
        if(profile==4&&x!=90)tile.LiquidAmount=0;
        if(x==90&&y==100){if(profile==1)tile.Flags|=WorldTileFlags.Active;if(profile==2)tile.LiquidAmount=254;if(profile==3)tile.LiquidKind=WorldLiquidKind.Water;}
        if(x==90&&y==roof&&profile==5)tile.Type=19;
        if(x==89&&y==roof){if(profile==6)tile.Flags|=WorldTileFlags.WireRed;if(profile==7)tile.Flags|=WorldTileFlags.WireBlue;}
        if(x==90&&y==roof+2)tile.Type=(ushort)(profile switch{8=>41,9=>225,10=>226,20=>677,21=>678,22=>679,23=>481,24=>482,25=>483,_=>1});
        if(x==90&&y==floor)tile.Type=(ushort)(profile switch{14=>162,15=>19,_=>1});
        if(profile==16&&x==90&&y>=floor)tile.Flags&=~WorldTileFlags.Active;
        if(profile==17&&x==90&&y==roof+4)tile.LiquidAmount=1;
        if(profile>=18){tile.TrySetSourceShape((x+y)%3==0,(byte)((x+y)%5));tile.Flags|=WorldTileFlags.Actuator;if(profile==19)tile.Flags|=WorldTileFlags.Inactive;}
        return tile;
    }
    private static WorldTile CampTile(int profile,int x,int y)
    {
        int key=(x*13+y*7)%31;ushort type=profile switch{0=>1,1=>0,2=>147,3=>53,4=>60,5=>367,6=>368,7=>(ushort)(key%6 switch{0=>53,1=>147,2=>60,3=>367,4=>368,_=>1}),_=>1};
        var tile=new WorldTile{Type=type,Wall=(ushort)(profile==12?0:15),FrameX=18,FrameY=36,TileColor=7,WallColor=9,Flags=WorldTileFlags.Active};
        if(profile==8&&x==90&&y==90||profile==9&&x%3==0&&y%3==0)tile.Flags&=~WorldTileFlags.Active;
        if(profile==10&&x==90&&y==90)tile.Type=226;if(profile==11&&x==90&&y==90)tile.Type=237;
        if(profile>=13){tile.Flags|=WorldTileFlags.WireRed|WorldTileFlagMasks.Visibility|WorldTileFlagMasks.Fullbright;tile.LiquidAmount=(byte)(key*8);tile.LiquidKind=(WorldLiquidKind)(profile%4);}
        if(profile==14)tile.TrySetSourceShape(key%3==0,(byte)(key%5));if(profile==15)tile.Flags|=WorldTileFlags.Inactive;
        return tile;
    }
    private sealed class LeafRandom(int seed):IWorldGenerationVanillaRandom
    {
        internal readonly VanillaUnifiedRandom1458 Source=new(seed);
        public int Next()=>Source.Next();public int Next(int max)=>Source.Next(max);public int Next(int min,int max)=>Source.Next(min,max);public double NextDouble()=>Source.NextDouble();public void NextBytes(byte[] bytes)=>Source.NextBytes(bytes);
    }
